# Všechny kontroly projektu spouští jeden příkaz: make check
.PHONY: check check-changed test test-domain infection infection-full phpstan phpstan-legacy rector deptrac symfony

# Mutační testy běží jen na řádcích změněných od posledního tagu cvičení
# (mNN-start). Jiný základ: make check INFECTION_BASE=main
INFECTION_BASE ?= $(shell git describe --tags --abbrev=0 --match 'm[0-9][0-9]-start' 2>/dev/null || echo HEAD)

PHPSTAN ?= vendor/bin/phpstan
PHPSTAN_FLAGS ?=
RECTOR_FLAGS ?=

check: test infection phpstan phpstan-legacy rector deptrac symfony

test:
	vendor/bin/phpunit --no-progress

# Rychlá vnitřní smyčka: doménové testy bez jádra Symfony a bez databáze.
test-domain:
	vendor/bin/phpunit --no-progress --testsuite domain

# Změněné řádky, ve kterých Infection nenajde nic k mutaci (třeba jen volání),
# práh MSI neshodí.
infection:
	@if git diff --quiet $(INFECTION_BASE) -- src; then \
		echo "Infection: žádné změněné řádky v src/ od $(INFECTION_BASE)"; \
	else \
		vendor/bin/infection --git-diff-lines --git-diff-base=$(INFECTION_BASE) \
			--threads=1 --no-progress --show-mutations --min-covered-msi=80 \
			--ignore-msi-with-no-mutations; \
	fi

# Celý běh Infection (CI jednou týdně).
infection-full:
	vendor/bin/infection --threads=1 --no-progress

# PHPStan potřebuje XML kontejneru (phpstan-symfony), proto nejdřív cache:warmup.
phpstan:
	@bin/console cache:warmup --quiet
	@$(PHPSTAN) analyse --no-progress --error-format=raw --memory-limit=1G $(PHPSTAN_FLAGS) && echo "PHPStan: bez chyb"

# Stará administrace: jen pravidla na nebezpečné vzory (zápis do orders/stock_items,
# hodnoty přilepené do SQL). Staré výskyty jsou v baseline, hlásí se jen nové.
phpstan-legacy:
	@$(PHPSTAN) analyse -c phpstan-legacy.neon --no-progress --error-format=raw --memory-limit=1G $(PHPSTAN_FLAGS) && echo "PHPStan (stará administrace): bez nových nebezpečných vzorů"

# Rector nanečisto: selže, když by v kódu něco přepsal.
rector:
	@vendor/bin/rector process --dry-run --no-progress-bar $(RECTOR_FLAGS)

# Hranice mezi ohraničenými kontexty. Třída mimo všechny vrstvy je chyba
# (--report-uncovered vypíše, která závislost to je).
deptrac:
	@vendor/bin/deptrac analyse --fail-on-uncovered --report-uncovered --no-progress

# Kontejner a mapování Doctrine (bez porovnání s databází).
symfony:
	@bin/console lint:container
	@bin/console doctrine:schema:validate --skip-sync

# Rychlá kontrola po editaci: PHPStan jen na změněné a nové soubory. Volají ji hooky
# všech nástrojů. Chyby jdou na stderr a make při chybě končí kódem 2, takže je agent
# dostane zpátky jako zpětnou vazbu. Změněné soubory staré administrace kontroluje
# phpstan-legacy.neon (jen nebezpečné vzory, staré výskyty v baseline). Při změně
# v src/ běží i Deptrac (hranice platí i pro starou administraci).
check-changed:
	@changed=$$( { git diff --name-only --diff-filter=d HEAD; git ls-files --others --exclude-standard; } \
		| grep -E '^(src|tests|tools)/.*\.php$$' | sort -u ); \
	files=$$(echo "$$changed" | grep -v '^src/Legacy/'); \
	legacy=$$(echo "$$changed" | grep '^src/Legacy/' | grep -v '^src/Legacy/templates/'); \
	status=0; \
	if [ -n "$$legacy" ]; then \
		$(PHPSTAN) analyse -c phpstan-legacy.neon --no-progress --error-format=raw --memory-limit=1G $(PHPSTAN_FLAGS) $$legacy 1>&2 || status=2; \
	fi; \
	if [ -n "$$files" ]; then \
		bin/console cache:warmup --quiet; \
		$(PHPSTAN) analyse --no-progress --error-format=raw --memory-limit=1G $(PHPSTAN_FLAGS) $$files 1>&2 || status=2; \
	fi; \
	if echo "$$changed" | grep -q '^src/'; then \
		vendor/bin/deptrac analyse --fail-on-uncovered --report-uncovered --no-progress 1>&2 || status=2; \
	fi; \
<?php
/**
 * Most mezi Symfony a starou administraci (2024).
 *
 * Symfony routa /admin/legacy/{page} -> __invoke(). Stara administrace cte
 * superglobalni promenne, takze sem prekopirujeme query/post z Requestu,
 * spustime controller nebo proceduralni stranku pod ob_start() a vystup
 * vratime jako Response.
 *
 * Jedine misto v src/Legacy, ktere zna Symfony.
 */

namespace App\Legacy\Http;

use App\Legacy\Admin\AdminController;
use App\Legacy\Admin\CustomerController;
use App\Legacy\Admin\ExportController;
use App\Legacy\Admin\InvoiceController;
use App\Legacy\Admin\OrderController;
use App\Legacy\Admin\ProductController;
use App\Legacy\Admin\ReportController;
use App\Legacy\Admin\StockController;
use App\Legacy\Admin\UserController;
use App\Legacy\lib\AccessDenied;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Messenger\Exception\HandlerFailedException;
use Symfony\Component\Messenger\MessageBusInterface;
use Symfony\Component\Messenger\Stamp\HandledStamp;
use Symfony\Component\Security\Core\User\UserInterface;
use Symfony\Component\Security\Http\Attribute\CurrentUser;

class LegacyFrontController
{
    public function __construct(
        // vychozi sbernice je command.bus (config/packages/messenger.yaml)
        private MessageBusInterface $commandBus,
    ) {
    }

    /**
     * Role Symfony uzivatele -> role stare administrace (admin_users.role).
     * Prvni nalezena vyhrava; personal bez nich smi jen stranky s auth_require() bez role.
     */
    private static $roles = array(
        'ROLE_ADMIN'  => 'admin',
        'ROLE_OBCHOD' => 'obchod',
        'ROLE_UCETNI' => 'ucetni',
        'ROLE_SKLAD'  => 'sklad',
    );

    /**
     * Povolene stranky: page => array(trida, metoda) nebo nazev souboru v Admin/.
     */
    private static $pages = array(
        // "MVC" controllery (2017+)
        'dashboard'          => array(AdminController::class, 'dashboardAction'),
        'search'             => array(AdminController::class, 'searchAction'),
        'report'             => array(ReportController::class, 'monthlyAction'),
        'report_year'        => array(ReportController::class, 'yearAction'),
        'report_top'         => array(ReportController::class, 'topAction'),
        'orders'             => array(OrderController::class, 'listAction'),
        'order'              => array(OrderController::class, 'detailAction'),
        'customer_orders'    => array(OrderController::class, 'byCustomerAction'),
        'customers'          => array(CustomerController::class, 'listAction'),
        'customer'           => array(CustomerController::class, 'detailAction'),
        'customer_delete'    => array(CustomerController::class, 'deleteAction'),
        'customer_anonymize' => array(CustomerController::class, 'anonymizeAction'),
        'products'           => array(ProductController::class, 'listAction'),
        'products_bulk_price'=> array(ProductController::class, 'bulkPriceAction'),
        'product_toggle'     => array(ProductController::class, 'toggleAction'),
        'stock'              => array(StockController::class, 'listAction'),
        'stock_reservations' => array(StockController::class, 'reservationsAction'),
        'stock_inventory'    => array(StockController::class, 'inventoryAction'),
        'user_list'          => array(UserController::class, 'listAction'),
        'user_save'          => array(UserController::class, 'saveAction'),
        'user_delete'        => array(UserController::class, 'deleteAction'),
        'invoices'           => array(InvoiceController::class, 'listAction'),
        'invoice'            => array(InvoiceController::class, 'detailAction'),
        'invoice_issue'      => array(InvoiceController::class, 'issueAction'),
        'export'             => array(ExportController::class, 'indexAction'),
        'export_csv'         => array(ExportController::class, 'ordersAction'),
        'export_customers'   => array(ExportController::class, 'customersAction'),

        // proceduralni stranky (2014–2016)
        'order_edit'         => 'order_edit.php',
        'orders_bulk'        => 'orders.php',
        'order_list'         => 'order_list.php',
        'order_notes'        => 'order_notes.php',
        'unpaid_orders'      => 'unpaid_orders.php',
        'users'              => 'users.php',
        'login'              => 'login.php',
        'logout'             => 'logout.php',
        'stats'              => 'stats.php',
        'chart'              => 'chart.php',
        'monthly'            => 'monthly.php',
        'customer_edit'      => 'customer_edit.php',
        'customer_export'    => 'customer_export.php',
        'product_edit'       => 'product_edit.php',
        'newsletter'         => 'newsletter.php',
        'settings'           => 'settings.php',
        'audit'              => 'audit.php',
        'invoice_print'      => 'invoice_print.php',
        'stock_report'       => 'stock_report.php',
        'top_products'       => 'top_products.php',
        'suppliers'          => 'suppliers.php',
        'exchange_rates'     => 'exchange_rates.php',
        'sales_by_currency'  => 'sales_by_currency.php',

        // akce, ktere meni objednavku prikazem noveho e-shopu (2026)
        'order_item_quantity'=> array(OrderController::class, 'changeItemQuantityAction'),
    );

    public function __invoke(Request $request, string $page = 'dashboard', #[CurrentUser] ?UserInterface $user = null): Response
    {
        require_once __DIR__ . '/../bootstrap.php';

        if (!isset(self::$pages[$page])) {
            return new Response('<h1>404</h1><p>Stránka neexistuje.</p>', 404);
        }

        // stara administrace cte superglobaly
        $_GET = $request->query->all();
        $_POST = $request->request->all();
        $_REQUEST = array_merge($_GET, $_POST);
        $_SERVER['REQUEST_METHOD'] = $request->getMethod();

        // prihlaseny uzivatel pro auth_user()/auth_require() a token pro csrf_check()
        $GLOBALS['LEGACY_USER'] = $user === null ? null : self::legacyUser($user);
        $GLOBALS['LEGACY_CSRF_TOKEN'] = self::csrfToken($request);

        $GLOBALS['LEGACY_REDIRECT'] = null;
        $GLOBALS['LEGACY_STATUS'] = 200;
        $GLOBALS['LEGACY_CONTENT_TYPE'] = 'text/html; charset=utf-8';
        $GLOBALS['LEGACY_FILENAME'] = null;

        // prikazy noveho e-shopu, stara administrace je vola pres legacy_command()
        $GLOBALS['LEGACY_COMMAND'] = function ($command) {
            try {
                $envelope = $this->commandBus->dispatch($command);
            } catch (HandlerFailedException $e) {
                // stara administrace chyta domenove vyjimky, ne obalku Messengeru
                $wrapped = $e->getWrappedExceptions();
                throw $wrapped ? reset($wrapped) : $e;
            }
            $handled = $envelope->last(HandledStamp::class);

            return $handled !== null ? $handled->getResult() : null;
        };

        $target = self::$pages[$page];
        $level = ob_get_level();
        ob_start();
        try {
            if (is_array($target)) {
                $controller = new $target[0]();
                $result = call_user_func(array($controller, $target[1]));
                $html = ob_get_clean() . (is_string($result) ? $result : '');
            } else {
                $this->includePage(__DIR__ . '/../Admin/' . $target);
                $html = ob_get_clean();
            }
        } catch (AccessDenied $e) {
            // auth_require() nebo csrf_check(); driv die()
            return new Response('<h1>403</h1><p>' . htmlspecialchars($e->getMessage(), ENT_QUOTES, 'UTF-8') . '</p>', 403);
        } finally {
            while (ob_get_level() > $level) {
                ob_end_clean();
            }
            // uzivatel a token patri jen tomuto pozadavku
            unset($GLOBALS['LEGACY_USER'], $GLOBALS['LEGACY_CSRF_TOKEN']);
        }

        if (!empty($GLOBALS['LEGACY_REDIRECT'])) {
            return new Response('', 302, array('Location' => $GLOBALS['LEGACY_REDIRECT']));
        }

        $response = new Response($html, (int) $GLOBALS['LEGACY_STATUS']);
        $response->headers->set('Content-Type', $GLOBALS['LEGACY_CONTENT_TYPE']);
        if (!empty($GLOBALS['LEGACY_FILENAME'])) {
            $response->headers->set('Content-Disposition', 'attachment; filename="' . $GLOBALS['LEGACY_FILENAME'] . '"');
        }

        return $response;
    }

    /**
     * Symfony uzivatel ve tvaru radku admin_users, jak ho cte auth_user().
     */
    private static function legacyUser(UserInterface $user)
    {
        $role = '';
        foreach (self::$roles as $symfonyRole => $legacyRole) {
            if (in_array($symfonyRole, $user->getRoles(), true)) {
                $role = $legacyRole;
                break;
            }
        }

        return array('id' => null, 'login' => $user->getUserIdentifier(), 'role' => $role);
    }

    /**
     * Jeden CSRF token na session (viz lib/csrf.php).
     */
    private static function csrfToken(Request $request)
    {
        $session = $request->getSession();
        $token = $session->get('legacy_csrf_token');
        if (!is_string($token) || $token === '') {
            $token = bin2hex(random_bytes(32));
            $session->set('legacy_csrf_token', $token);
        }

        return $token;
    }

    /**
     * Include ve vlastnim scope, at si stranky neprepisuji promenne mostu.
     */
    private function includePage($file)
    {
        include $file;
    }
}
<?php

declare(strict_types=1);

namespace App\Tests\Acceptance\Legacy;

use App\Identity\Infrastructure\Security\DemoCustomerProvider;
use App\Ordering\Domain\Model\Order;
use App\Ordering\Domain\Repository\OrderRepository;
use App\Ordering\Domain\ValueObject\CustomerId;
use App\Ordering\Domain\ValueObject\OrderId;
use App\Ordering\Domain\ValueObject\ProductId;
use App\SharedKernel\Domain\Currency;
use App\SharedKernel\Domain\Money;
use App\Tests\Support\Catalog;
use App\Tests\Support\TestDatabase;
use Doctrine\DBAL\Connection;
use Doctrine\ORM\EntityManagerInterface;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Bundle\FrameworkBundle\KernelBrowser;
use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;

/**
 * Akceptační kritérium 1 z docs/plany/zmena-mnozstvi.md: množství jde změnit
 * jen u rozpracované objednávky, i ze staré administrace.
 */
final class ChangeItemQuantityTest extends WebTestCase
{
    private KernelBrowser $client;

    protected function setUp(): void
    {
        TestDatabase::reset();
        // stará administrace drží spojení v globální proměnné
        $GLOBALS['db'] = null;
        $this->client = self::createClient();
        $this->client->disableReboot();
        Catalog::seed(self::getContainer()->get(Connection::class));
        $this->client->loginUser(
            self::getContainer()->get(DemoCustomerProvider::class)->loadUserByIdentifier('sprava@example.com'),
        );
    }

    #[Test]
    public function quantityInConfirmedOrderStaysUnchanged(): void
    {
        // příprava: potvrzená objednávka, klávesnice 2 × 300 Kč, sleva 100 Kč
        $orders = self::getContainer()->get(OrderRepository::class);
        $order = Order::place(OrderId::generate(), CustomerId::generate());
        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 2, new Money(300_00, Currency::CZK));
        $order->applyDiscount(new Money(100_00, Currency::CZK));
        $order->confirm();
        $orders->save($order);

        // akce: obsluha ve staré administraci změní množství na 3 kusy
        $this->client->request(
            'POST',
            '/admin/legacy/order_item_quantity?id='.$order->id->value,
            ['product' => Catalog::KEYBOARD, 'quantity' => '3'],
        );

        // ověření: chyba, množství i částky beze změny
        self::assertSelectorTextContains('.flash.error', 'rozpracované objednávky');
        self::getContainer()->get(EntityManagerInterface::class)->clear();
        $unchanged = $orders->get($order->id);
        self::assertSame(2, $unchanged->items[0]->quantity);
        self::assertSame(600_00, $unchanged->totalAmount()->amountInCents);
        self::assertSame(500_00, $unchanged->paidAmount()->amountInCents);
    }

    #[Test]
    public function quantityInDraftOrderChangesFromOrderDetail(): void
    {
        $order = Order::place(OrderId::generate(), CustomerId::generate());
        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 2, new Money(300_00, Currency::CZK));
        self::getContainer()->get(OrderRepository::class)->save($order);

        $this->client->request('GET', '/admin/legacy/order?id='.$order->id->value);
        $this->client->submitForm('Změnit', ['quantity' => '3']);

        self::assertSelectorTextContains('.flash', 'Množství položky změněno');
        self::getContainer()->get(EntityManagerInterface::class)->clear();
        self::assertSame(3, self::getContainer()->get(OrderRepository::class)->get($order->id)->items[0]->quantity);
    }
}
